const read = () => page.evaluate(() => {
  const leaf = Array.from(document.querySelectorAll('*')).find(e => e.children.length===0 && /Performance Plan - Service Pricing/i.test(e.textContent));
  if (!leaf) return {found:false, url: location.href};
  let el = leaf; while (el && !/STORAGE TIER/.test(el.innerText)) el = el.parentElement;
  const sw = Array.from(el.querySelectorAll('[role=switch],button[aria-checked],input[type=checkbox]'));
  return {found:true, switches: sw.map(s=>({aria:s.getAttribute('aria-checked'), state:s.getAttribute('data-state'), checked:s.checked})), text: el.innerText.slice(0,1500)};
});
const a = await read();
console.log("STATE A", JSON.stringify(a.switches), "\n", a.text);
if (a.found) {
  await page.evaluate(() => {
    const leaf = Array.from(document.querySelectorAll('*')).find(e => e.children.length===0 && /Performance Plan - Service Pricing/i.test(e.textContent));
    let el = leaf; while (el && !/STORAGE TIER/.test(el.innerText)) el = el.parentElement;
    el.querySelector('[role=switch],button[aria-checked],input[type=checkbox]').click();
  });
  await page.waitForTimeout(1500);
  const b = await read();
  console.log("STATE B", JSON.stringify(b.switches), "\n", b.text);
}
EOF
firecrawl interact -s 01a14b38-4397-754a-8959-932ebfa2cce3 --timeout 90 --code "$(cat /tmp/tiger2.js)" 2>&1 | tee tiger-code.txt | tail -120

